"""Every rounding rule of meterbill lives here."""

from __future__ import annotations

import math
from decimal import ROUND_DOWN, ROUND_HALF_EVEN, ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _ratio(value: Decimal, step: Decimal):
    """value / step as an exact fraction (num, den) of non-negative integers."""
    vs, vd, ve = value.as_tuple()
    ss, sd, se = step.as_tuple()
    vc = int("".join(map(str, vd)))
    sc = int("".join(map(str, sd)))
    shift = ve - se
    if shift >= 0:
        return vc * 10**shift, sc
    return vc, sc * 10**(-shift)


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`, ties and direction by `method`."""
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")
    num, den = _ratio(value, step)
    k, r = divmod(num, den)
    if method == HALF_UP:
        if 2 * r >= den:
            k += 1
    elif method == HALF_EVEN:
        if 2 * r > den or (2 * r == den and k % 2 == 1):
            k += 1
    sc = int("".join(map(str, step.as_tuple().digits)))
    digits = tuple(int(c) for c in str(k * sc))
    return Decimal((1 if value.is_signed() else 0, digits, step.as_tuple().exponent))


def _down(value: Decimal, step: Decimal) -> Decimal:
    return round_amount(value, step, DOWN)


def allocate(amounts: list, step: Decimal) -> list:
    """Split the rounded sum of `amounts` into one multiple of `step` per amount.

    Each amount is cut toward zero; what the cuts lost against the half-up
    rounded total goes on the last amount that is not zero.
    """
    parts = [_down(a, step) for a in amounts]
    whole = round_amount(sum(amounts, Decimal("0")), step, HALF_UP)
    zero = round_amount(Decimal("0"), step, DOWN)
    rest = whole - sum(parts, zero)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] += rest
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    """A float amount as the old customer system settled it (binary floats, half up)."""
    if isinstance(places, bool) or not isinstance(places, int) or not 0 <= places <= 6:
        raise ValueError("places must be an integer from 0 to 6")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point."""
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float can only be written half even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    return format(round_amount(value, Decimal(1).scaleb(-places), method), "f")
